const { withAppBuildGradle } = require("expo/config-plugins");

/**
 * Teaches the generated `android/app/build.gradle` to sign release builds with a
 * real upload key instead of the debug keystore Expo wires up by default.
 *
 * `android/` is gitignored and regenerated by `expo prebuild`, so this cannot be
 * a hand edit — it has to run as a plugin every time the project is generated.
 *
 * The key itself never lives in the repo. Gradle reads four properties, which
 * `scripts/release.ps1` passes from a file outside both the repo and the C:\rfb
 * build copy. When they are absent the build falls back to debug signing, so a
 * plain `assembleRelease` still produces the sideloadable APK it always did.
 */
const PROPS = [
  "ROZAKOS_UPLOAD_STORE_FILE",
  "ROZAKOS_UPLOAD_STORE_PASSWORD",
  "ROZAKOS_UPLOAD_KEY_ALIAS",
  "ROZAKOS_UPLOAD_KEY_PASSWORD",
];

const RELEASE_SIGNING_CONFIG = `        release {
            if (project.hasProperty('ROZAKOS_UPLOAD_STORE_FILE')) {
                storeFile file(ROZAKOS_UPLOAD_STORE_FILE)
                storePassword ROZAKOS_UPLOAD_STORE_PASSWORD
                keyAlias ROZAKOS_UPLOAD_KEY_ALIAS
                keyPassword ROZAKOS_UPLOAD_KEY_PASSWORD
            }
        }
`;

const SIGNING_SELECTOR =
  "signingConfig project.hasProperty('ROZAKOS_UPLOAD_STORE_FILE') " +
  "? signingConfigs.release : signingConfigs.debug";

const GENERATED_DEBUG_CONFIG = `        debug {
            storeFile file('debug.keystore')
            storePassword 'android'
            keyAlias 'androiddebugkey'
            keyPassword 'android'
        }
`;

const GENERATED_RELEASE_BUILD_TYPE = `        release {
            // Caution! In production, you need to generate your own keystore file.
            // see https://reactnative.dev/docs/signed-apk-android.
            signingConfig signingConfigs.debug`;

/**
 * The pure half, exported so it can be exercised against a real generated
 * build.gradle without sitting through a ten-minute prebuild. Idempotent.
 *
 * Both anchors are asserted rather than silently skipped: a quiet no-op here
 * would mean shipping a debug-signed release, which Play rejects only after the
 * whole build has run.
 */
function applySigningToGradle(gradle) {
  if (gradle.includes(PROPS[0])) return gradle; // already applied

  if (!gradle.includes(GENERATED_DEBUG_CONFIG)) {
    throw new Error(
      "with-upload-signing: could not find the generated debug signingConfig. " +
        "The Expo build.gradle template changed - update this plugin.",
    );
  }
  if (!gradle.includes(GENERATED_RELEASE_BUILD_TYPE)) {
    throw new Error(
      "with-upload-signing: could not find the release buildType signingConfig. " +
        "The Expo build.gradle template changed - update this plugin.",
    );
  }

  return gradle
    .replace(GENERATED_DEBUG_CONFIG, GENERATED_DEBUG_CONFIG + RELEASE_SIGNING_CONFIG)
    .replace(GENERATED_RELEASE_BUILD_TYPE, "        release {\n            " + SIGNING_SELECTOR);
}

module.exports = function withUploadSigning(config) {
  return withAppBuildGradle(config, (cfg) => {
    cfg.modResults.contents = applySigningToGradle(cfg.modResults.contents);
    return cfg;
  });
};

module.exports.applySigningToGradle = applySigningToGradle;
